var n=`1107-burmese-curry`;var t=`world-1107`;var s=`MM`;var a=`southeast-asia`;var r=4;var o=78;var u={en:`Burmese Curry`,ua:`Бірманське карі`};var g={en:`Burmese Curry is a dish from Myanmar prepared with yellow onion, garlic, chicken thigh, tomato. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Бірманське карі, страва кухні країни М'янма, яку готують із таких продуктів: жовта цибуля, часник, куряче стегно, помідор. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,210,`g`],[`garlic`,5,`clove`],[`ground-ginger`,32,`g`],[`ground-turmeric`,6,`g`],[`canola-oil`,45,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 55 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 55 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:55,i:[[`chicken-thigh`,850,`g`],[`tomato`,280,`g`],[`water`,450,`ml`],[`fish-sauce`,35,`ml`]]},{en:`Continue simmering the sauce from the previous step uncovered until concentrated and thick enough to coat the ingredients.`,ua:`Продовжуйте виварювати соус із попереднього етапу без кришки, доки він загусне та вкриватиме складники.`,t:[`reducing-sauce`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,30,`g`]]}];var h={slug:n,id:t,country:`MM`,region:a,servings:4,minutes:78,title:u,text:g,steps:d};export{s as country,h as default,t as id,o as minutes,a as region,r as servings,n as slug,d as steps,g as text,u as title};